#!/usr/bin/env bash
# Fails if the editor's served drag script differs from what its TypeScript
# builds to: internal/editor/static/drag.js is generated by
# scripts/build-editor-script.sh (through go generate) and never edited by
# hand. It is a script, not a Go test, because only the operating system
# adapters may start programs (the repository's operating system check).
#
# Line endings are compared as LF, since Git on Windows may check the file out
# with CRLF, which is not a drift.
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
scratch="$(mktemp -d)"
trap 'rm -rf "$scratch"' EXIT

"$root/scripts/build-editor-script.sh" "$scratch/drag.js"

if ! diff -q <(tr -d '\r' <"$scratch/drag.js") <(tr -d '\r' <"$root/internal/editor/static/drag.js") >/dev/null; then
	echo "internal/editor/static/drag.js differs from internal/editor/web/drag.ts; run go generate ./internal/editor/" >&2
	exit 1
fi

echo "The editor's drag script matches its TypeScript."
